// Recibir datos del workflow principal desde el normalizador Code2
const solicitud = $('Code2').first().json;

// Obtener TODOS los turnos ocupados usando .all()
const pilar1Ocupados = $('CORDOBA_1').all().map(item => item.json).flat();
const pilar2Ocupados = $('CORDOBA_2').all().map(item => item.json).flat();

// Convertir tiempo HH:MM a minutos
function timeToMinutes(timeStr) {
  const [hours, minutes] = timeStr.split(':').map(Number);
  return hours * 60 + minutes;
}

// Función para verificar si hay conflicto de horarios
function tieneConflicto(solicitudFecha, solicitudInicio, solicitudFin, ocupados) {
  if (!Array.isArray(ocupados) || ocupados.length === 0) {
    return false;
  }

  const solicitudInicioMin = timeToMinutes(solicitudInicio);
  const solicitudFinMin = timeToMinutes(solicitudFin);

  return ocupados.some(ocupado => {
    // Verificar mismo día
    if (ocupado.dia !== solicitudFecha) return false;

    const ocupadoInicioMin = timeToMinutes(ocupado.inicio);
    const ocupadoFinMin = timeToMinutes(ocupado.final);

    // Verificar solapamiento (cualquier intersección)
    return (solicitudInicioMin < ocupadoFinMin && solicitudFinMin > ocupadoInicioMin);
  });
}

// Extraer fecha y horarios de la solicitud
const fechaISO = new Date(solicitud.Fecha);
const solicitudFecha = fechaISO.toISOString().split('T')[0]; // YYYY-MM-DD

// Extraer hora directamente del string ISO
const solicitudInicio = solicitud.Fecha.split('T')[1].substring(0, 5); // HH:MM
const solicitudFin = solicitud.Fin.split('T')[1].substring(0, 5); // HH:MM

// IDs de los calendarios
const PILAR_1_ID = "58622da0b58e9d801afe2b5619058187dacb72f5b6221ad36ddfdc8fb4dff85f@group.calendar.google.com";
const PILAR_2_ID = "7179fff29ae72e0ff4f09d095df63f4e3085833bf42f6f0badd8a212c315031a@group.calendar.google.com";

// Verificar disponibilidad
const pilar1Disponible = !tieneConflicto(solicitudFecha, solicitudInicio, solicitudFin, pilar1Ocupados);
const pilar2Disponible = !tieneConflicto(solicitudFecha, solicitudInicio, solicitudFin, pilar2Ocupados);

let calendarioElegido;
let boxAsignado;
let error = null;

if (pilar1Disponible && pilar2Disponible) {
  // Ambos disponibles, elegir PILAR_1 por defecto
  calendarioElegido = PILAR_1_ID;
  boxAsignado = "BOX 3: Asesor KEVIN";
} else if (pilar1Disponible) {
  calendarioElegido = PILAR_1_ID;
  boxAsignado = "BOX 3: Asesor KEVIN";
} else if (pilar2Disponible) {
  calendarioElegido = PILAR_2_ID;
  boxAsignado = "BOX 14: Asesor NICOLAS";
} else {
  // Ninguno disponible
  error = "No hay calendarios disponibles para el horario solicitado";
}

// Preparar respuesta
if (error) {
  return [{
    json: {
      error: error,
      solicitud: solicitud
    }
  }];
} else {
  const respuesta = {
    ...solicitud,
    Calendar: calendarioElegido,
    box: boxAsignado
  };

  return [{
    json: respuesta
  }];
}

// Normalizador de datos - maneja todas las estructuras posibles
function extraerDatos(input) {
  // Casos posibles de entrada
  let datos;

  // Caso 1: Webhook con body
  if (input.body) {
    datos = input.body;
  }
  // Caso 2: Datos directos
  else {
    datos = input;
  }

  // Si es array, tomar el primer elemento
  if (Array.isArray(datos)) {
    datos = datos[0];
  }

  // Si tiene query, extraerlo
  if (datos.query) {
    // Si query es string, parsearlo
    if (typeof datos.query === 'string') {
      datos = JSON.parse(datos.query);
    } else {
      datos = datos.query;
    }
  }

  // Si después del parse es array, tomar primer elemento
  if (Array.isArray(datos)) {
    datos = datos[0];
  }

  return datos;
}

// Obtener datos de entrada
const inputData = $json;
const solicitud = extraerDatos(inputData);

// Devolver datos limpios
return [{
  json: solicitud
}];

const items = $input.all();
const returnItems = [];

// Verificar si hay items
if (!items || items.length === 0) {
  return [];
}

for (const item of items) {
  // Verificar que el item tenga la estructura correcta
  if (!item || !item.json || !item.json.start || !item.json.start.dateTime) {
    continue; // Saltar este item si no tiene la estructura correcta
  }

  let data = item.json;

  const dia = data.start.dateTime.split('T')[0];
  const inicio = data.start.dateTime.split('T')[1].substring(0, 5);
  const final = data.end.dateTime.split('T')[1].substring(0, 5);

  returnItems.push({
    json: {
      dia: dia,
      inicio: inicio, 
      final: final
    }
  });
}

return returnItems;

